class EmployeeManagementScreen extends ConsumerWidget {
 const EmployeeManagementScreen({super.key, required this.canManage}); final bool canManage;
 @override Widget build(BuildContext context, WidgetRef ref) {
  final rows=ref.watch(employeeListProvider); final teams=ref.watch(employeeTeamsProvider);
  return Scaffold(appBar:AppBar(title:const Text('Employee Management'),actions:[if(canManage)IconButton(onPressed:()=>_openForm(context,ref),icon:const Icon(Icons.person_add_alt_1),tooltip:'Add employee')]),body:Column(children:[
   Padding(padding:const EdgeInsets.fromLTRB(16,16,16,8),child:TextField(decoration:const InputDecoration(prefixIcon:Icon(Icons.search),hintText:'Search name, employee code or phone',border:OutlineInputBorder()),onChanged:(v)=>ref.read(employeeSearchProvider.notifier).state=v)),
   Padding(padding:const EdgeInsets.symmetric(horizontal:16),child:Row(children:[Expanded(child:DropdownButtonFormField<EmployeeStatus?>(value:ref.watch(employeeStatusFilterProvider),decoration:const InputDecoration(labelText:'Status',border:OutlineInputBorder()),items:[const DropdownMenuItem(value:null,child:Text('All statuses')),...EmployeeStatus.values.map((s)=>DropdownMenuItem(value:s,child:Text(s.label)))],onChanged:(v)=>ref.read(employeeStatusFilterProvider.notifier).state=v)),const SizedBox(width:8),Expanded(child:teams.when(data:(list)=>DropdownButtonFormField<String?>(value:ref.watch(employeeTeamFilterProvider),decoration:const InputDecoration(labelText:'Team',border:OutlineInputBorder()),items:[const DropdownMenuItem(value:null,child:Text('All teams')),...list.map((t)=>DropdownMenuItem(value:t.id,child:Text(t.name,overflow:TextOverflow.ellipsis)))],onChanged:(v)=>ref.read(employeeTeamFilterProvider.notifier).state=v),loading:()=>const LinearProgressIndicator(),error:(e,_)=>const Text('Teams unavailable')))])),
   const SizedBox(height:8),Expanded(child:rows.when(loading:()=>const Center(child:CircularProgressIndicator()),error:(e,_)=>Center(child:Padding(padding:const EdgeInsets.all(24),child:Column(mainAxisSize:MainAxisSize.min,children:[const Icon(Icons.cloud_off_outlined,size:42),Text('Employee records could not be loaded.\n$e',textAlign:TextAlign.center),FilledButton(onPressed:()=>ref.invalidate(employeeListProvider),child:const Text('Retry'))])),data:(list)=>list.isEmpty?const Center(child:Text('No employees match these filters.')):RefreshIndicator(onRefresh:()=>ref.refresh(employeeListProvider.future),child:ListView.separated(padding:const EdgeInsets.all(16),itemCount:list.length,separatorBuilder:(_,__)=>const SizedBox(height:8),itemBuilder:(ctx,i){final e=list[i];return Card(child:ListTile(leading:CircleAvatar(child:Text(e.fullName.isEmpty?'?':e.fullName[0].toUpperCase())),title:Text(e.fullName,style:const TextStyle(fontWeight:FontWeight.w600)),subtitle:Text('${e.code} • ${e.teamName??'No team'}\n${e.phone} • ${e.status.label}'),isThreeLine:true,trailing:const Icon(Icons.chevron_right),onTap:()=>Navigator.push(ctx,MaterialPageRoute<void>(builder:(_)=>EmployeeDetailsScreen(employeeId:e.id,canManage:canManage))).then((_){ref.invalidate(employeeListProvider);})));}))))
  ]));
 }
 void _openForm(BuildContext context,WidgetRef ref,[Employee? employee])=>Navigator.push(context,MaterialPageRoute<void>(builder:(_)=>EmployeeFormScreen(employee:employee))).then((_){ref.invalidate(employeeListProvider);});
}

class EmployeeDetailsScreen extends ConsumerWidget {
 const EmployeeDetailsScreen({super.key,required this.employeeId,required this.canManage});final String employeeId;final bool canManage;
 @override Widget build(BuildContext context,WidgetRef ref){final state=ref.watch(employeeDetailsProvider(employeeId));return Scaffold(appBar:AppBar(title:const Text('Employee Details'),actions:[if(canManage)PopupMenuButton<String>(onSelected:(v)=>state.whenData((e){if(v=='edit')Navigator.push(context,MaterialPageRoute<void>(builder:(_)=>EmployeeFormScreen(employee:e))).then((_){ref.invalidate(employeeDetailsProvider(employeeId));ref.invalidate(employeeListProvider);});if(v=='status')_changeStatus(context,ref,e);if(v=='transfer')_transfer(context,ref,e);if(v=='history')Navigator.push(context,MaterialPageRoute<void>(builder:(_)=>EmployeeHistoryScreen(employeeId:employeeId)));}),itemBuilder:(_)=>const [PopupMenuItem(value:'edit',child:Text('Edit profile')),PopupMenuItem(value:'status',child:Text('Change status')),PopupMenuItem(value:'transfer',child:Text('Transfer employee')),PopupMenuItem(value:'history',child:Text('Employee history'))])]),body:state.when(loading:()=>const Center(child:CircularProgressIndicator()),error:(e,_)=>Center(child:Text('Could not load employee: $e')),data:(e)=>ListView(padding:const EdgeInsets.all(18),children:[Card(child:Padding(padding:const EdgeInsets.all(20),child:Column(children:[CircleAvatar(radius:36,backgroundImage:e.profilePhotoUrl==null?null:NetworkImage(e.profilePhotoUrl!),child:e.profilePhotoUrl==null?Text(e.fullName.isEmpty?'?':e.fullName[0].toUpperCase()):null),const SizedBox(height:12),Text(e.fullName,style:Theme.of(context).textTheme.headlineSmall),Text('Employee code: ${e.code}'),Chip(label:Text(e.status.label))]))),_details('Contact',[('Phone',e.phone),('Email',e.email),('NIC',e.nic),('Address',e.address)]),_details('Employment',[('Role',e.role.label),('Team',e.teamName),('Date of birth',_date(e.dateOfBirth)),('Join date',_date(e.joinDate)),('Approval',e.approvalStatus)]),if(canManage)FilledButton.icon(onPressed:()=>Navigator.push(context,MaterialPageRoute<void>(builder:(_)=>EmployeeHistoryScreen(employeeId:employeeId))),icon:const Icon(Icons.history),label:const Text('View audit and transfer history'))])));}
 Widget _details(String title,List<(String,String?)> values)=>Card(margin:const EdgeInsets.only(bottom:12),child:Padding(padding:const EdgeInsets.all(16),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(title,style:const TextStyle(fontWeight:FontWeight.bold,fontSize:17)),const Divider(),...values.map((v)=>Padding(padding:const EdgeInsets.symmetric(vertical:5),child(Row(crossAxisAlignment:CrossAxisAlignment.start,children:[SizedBox(width:110,child:Text(v.$1,style:const TextStyle(color:Colors.black54))),Expanded(child:Text(v.$2==null||v.$2!.isEmpty?'—':v.$2!))])))])));
 String _date(DateTime? d)=>d==null?'—':'${d.year}-${d.month.toString().padLeft(2,'0')}-${d.day.toString().padLeft(2,'0')}';
 Future<void> _changeStatus(BuildContext context,WidgetRef ref,Employee e)async{final reason=TextEditingController();var status=e.status;final ok=await showDialog<bool>(context:context,builder:(ctx)=>StatefulBuilder(builder:(ctx,set)=>AlertDialog(title:const Text('Change employee status'),content:Column(mainAxisSize:MainAxisSize.min,children:[DropdownButtonFormField<EmployeeStatus>(value:status,items:EmployeeStatus.values.map((s)=>DropdownMenuItem(value:s,child:Text(s.label))).toList(),onChanged:(v){if(v!=null)set(()=>status=v);}),TextField(controller:reason,decoration:const InputDecoration(labelText:'Reason'),minLines:2,maxLines:3)]),actions:[TextButton(onPressed:()=>Navigator.pop(ctx,false),child:const Text('Cancel')),FilledButton(onPressed:()=>Navigator.pop(ctx,true),child:const Text('Save'))])));if(ok!=true||reason.text.trim().length<3)return;try{await EmployeeRepository().changeStatus(e,status,reason.text);ref.invalidate(employeeDetailsProvider(e.id));ref.invalidate(employeeListProvider);}catch(err){if(context.mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('Status update failed: $err')));}}
 Future<void> _transfer(BuildContext context,WidgetRef ref,Employee e)async{final reason=TextEditingController();final teams=await ref.read(employeeTeamsProvider.future);if(!context.mounted)return;String? team=e.teamId;final selected=await showDialog<String?>(context:context,builder:(ctx)=>StatefulBuilder(builder:(ctx,set)=>AlertDialog(title:const Text('Transfer employee'),content:Column(mainAxisSize:MainAxisSize.min,children:[DropdownButtonFormField<String?>(value:team,items:[const DropdownMenuItem(value:null,child:Text('Direct / no team')),...teams.map((t)=>DropdownMenuItem(value:t.id,child:Text(t.name)))],onChanged:(v)=>set(()=>team=v)),TextField(controller:reason,decoration:const InputDecoration(labelText:'Transfer reason'),minLines:2,maxLines:3)]),actions:[TextButton(onPressed:()=>Navigator.pop(ctx),child:const Text('Cancel')),FilledButton(onPressed:()=>Navigator.pop(ctx,team??'__none__'),child:const Text('Transfer'))])));if(selected==null||reason.text.trim().length<3)return;try{await EmployeeRepository().transfer(e,teamId:selected=='__none__'?null:selected,reportsToId:e.reportsToId,reason:reason.text);ref.invalidate(employeeDetailsProvider(e.id));ref.invalidate(employeeListProvider);}catch(err){if(context.mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('Transfer failed: $err')));}}
}

class EmployeeFormScreen extends ConsumerStatefulWidget {const EmployeeFormScreen({super.key,this.employee});final Employee? employee;@override ConsumerState<EmployeeFormScreen> createState()=>_EmployeeFormScreenState();}
class _EmployeeFormScreenState extends ConsumerState<EmployeeFormScreen>{final _form=GlobalKey<FormState>();late final TextEditingController code,name,phone,nic,address;DateTime? dob,joinDate;EmployeeRole role=EmployeeRole.agent;EmployeeStatus status=EmployeeStatus.active;String? teamId;bool saving=false;
 @override void initState(){super.initState();final e=widget.employee;code=TextEditingController(text:e?.code??'');name=TextEditingController(text:e?.fullName??'');phone=TextEditingController(text:e?.phone??'');nic=TextEditingController(text:e?.nic??'');address=TextEditingController(text:e?.address??'');dob=e?.dateOfBirth;joinDate=e?.joinDate;role=e?.role??EmployeeRole.agent;status=e?.status??EmployeeStatus.active;teamId=e?.teamId;}
 @override void dispose(){code.dispose();name.dispose();phone.dispose();nic.dispose();address.dispose();super.dispose();}
 @override Widget build(BuildContext context){final teams=ref.watch(employeeTeamsProvider);return Scaffold(appBar:AppBar(title:Text(widget.employee==null?'Add Employee':'Edit Employee')),body:Form(key:_form,child:ListView(padding:const EdgeInsets.all(18),children:[if(widget.employee==null)_field(code,'Employee code',true),_field(name,'Full name',true),_field(phone,'Phone number',true,keyboard:TextInputType.phone),_field(nic,'NIC',false),_field(address,'Address',false,maxLines:3),_dateField('Date of birth',dob,(v)=>setState(()=>dob=v)),_dateField('Join date',joinDate,(v)=>setState(()=>joinDate=v)),DropdownButtonFormField<EmployeeRole>(value:role,decoration:const InputDecoration(labelText:'Position / role',border:OutlineInputBorder()),items:EmployeeRole.values.map((v)=>DropdownMenuItem(value:v,child:Text(v.label))).toList(),onChanged:(v){if(v!=null)setState(()=>role=v);}),const SizedBox(height:12),DropdownButtonFormField<EmployeeStatus>(value:status,decoration:const InputDecoration(labelText:'Employee status',border:OutlineInputBorder()),items:EmployeeStatus.values.map((v)=>DropdownMenuItem(value:v,child:Text(v.label))).toList(),onChanged:(v){if(v!=null)setState(()=>status=v);}),const SizedBox(height:12),teams.when(data:(list)=>DropdownButtonFormField<String?>(value:teamId,decoration:const InputDecoration(labelText:'Assigned team',border:OutlineInputBorder()),items:[const DropdownMenuItem(value:null,child:Text('Direct / no team')),...list.map((t)=>DropdownMenuItem(value:t.id,child:Text(t.name)))],onChanged:(v)=>setState(()=>teamId=v)),loading:()=>const LinearProgressIndicator(),error:(e,_)=>Text('Could not load teams: $e')),const SizedBox(height:20),FilledButton(onPressed:saving?null:_save,child:Text(saving?'Saving…':'Save employee'))])));}
 Widget _field(TextEditingController c,String label,bool required,{TextInputType? keyboard,int maxLines=1})=>Padding(padding:const EdgeInsets.only(bottom:12),child:TextFormField(controller:c,keyboardType:keyboard,maxLines:maxLines,decoration:InputDecoration(labelText:label,border:const OutlineInputBorder()),validator:(v)=>required&&(v==null||v.trim().isEmpty)?'$label is required':null));
 Widget _dateField(String label,DateTime? date,ValueChanged<DateTime?> change)=>ListTile(title:Text(label),subtitle:Text(date==null?'Not set':'${date.year}-${date.month}-${date.day}'),trailing:const Icon(Icons.calendar_month),onTap:()async{final now=DateTime.now();final v=await showDatePicker(context:context,initialDate:date??now,firstDate:DateTime(1940),lastDate:DateTime(now.year+1));if(v!=null)change(v);});
 Future<void> _save()async{if(!_form.currentState!.validate())return;setState(()=>saving=true);try{final repo=ref.read(employeeRepositoryProvider);if(widget.employee==null){await repo.create(code:code.text,name:name.text,phone:phone.text,role:role,status:status,teamId:teamId,nic:nic.text,address:address.text,dob:dob,joinDate:joinDate);}else{await repo.update(employee:widget.employee!,name:name.text,phone:phone.text,role:role,status:status,teamId:teamId,nic:nic.text,address:address.text,dob:dob,joinDate:joinDate);}ref.invalidate(employeeListProvider);if(mounted){ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(widget.employee==null?'Employee created; approval is pending.':'Employee updated.')));Navigator.pop(context);}}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('Could not save employee: $e')));}finally{if(mounted)setState(()=>saving=false);}}
}

class EmployeeHistoryScreen extends ConsumerWidget{const EmployeeHistoryScreen({super.key,required this.employeeId});final String employeeId;@override Widget build(BuildContext context,WidgetRef ref){final data=ref.watch(employeeHistoryProvider(employeeId));return Scaffold(appBar:AppBar(title:const Text('Employee History')),body:data.when(loading:()=>const Center(child:CircularProgressIndicator()),error:(e,_)=>Center(child:Text('History unavailable: $e')),data:(events)=>events.isEmpty?const Center(child:Text('No history recorded yet.')):ListView.separated(padding:const EdgeInsets.all(16),itemCount:events.length,separatorBuilder:(_,__)=>const Divider(),itemBuilder:(ctx,i){final e=events[i];final kind=e['kind'].toString();final detail=kind=='Status'?' ${e['previous_status']??'New'} → ${e['new_status']??''}':kind=='Transfer'?' ${e['previous_team_id']??'—'} → ${e['new_team_id']??'—'}':' ${e['status']??''}';return ListTile(leading:const Icon(Icons.history),title:Text('$kind$detail'),subtitle:Text('${e['reason']??e['review_reason']??''}\n${e['changed_at']??e['transferred_at']??e['created_at']??''}'),isThreeLine:true);})));}}
